class RenderObjClass
{
public:
	virtual void Delete_This();
	int m_refCount;
};

class Shadow;

class W3DShadowManager
{
public:
	void removeShadow(Shadow *shadow);
};

class SceneClass
{
public:
	virtual void slot0();
	virtual void slot1();
	virtual void slot2();
	virtual void Remove_Render_Object(RenderObjClass *renderObject);
};

extern W3DShadowManager *TheW3DShadowManager;

class W3DDisplay
{
public:
	static SceneClass *m_3DScene;
};

class Module
{
public:
	~Module();
};

class DrawModule : public Module
{
public:
	virtual ~DrawModule() { }

private:
	char m_padding[8];
};

class W3DDefaultDraw : public DrawModule
{
protected:
	virtual ~W3DDefaultDraw();

private:
	RenderObjClass *m_renderObject;
	Shadow *m_shadow;
};

W3DDefaultDraw::~W3DDefaultDraw()
{
	if (TheW3DShadowManager && m_shadow)
	{
		TheW3DShadowManager->removeShadow(m_shadow);
		m_shadow = 0;
	}
	if (m_renderObject)
	{
		W3DDisplay::m_3DScene->Remove_Render_Object(m_renderObject);
		if (m_renderObject)
		{
			if (--m_renderObject->m_refCount == 0)
				m_renderObject->Delete_This();
		}
		m_renderObject = 0;
	}
}
